create or replace function public.get_academic_setup_health(p_school_id uuid)
returns jsonb language sql stable security definer set search_path=public,pg_temp as $$
select jsonb_build_object('issues',coalesce(jsonb_agg(to_jsonb(i) order by i.priority,i.title),'[]'::jsonb)) from (
 select 1 priority,'CLASS_WITHOUT_STREAM' code,'warning' severity,'Class without streams' title,c.class_name||' has no active stream.' detail,'/setup/classes/'||c.id path from public.academic_classes c where c.school_id=p_school_id and c.status='ACTIVE' and not exists(select 1 from public.class_streams s where s.class_id=c.id and s.status='ACTIVE')
 union all select 1,'CLASS_WITHOUT_TEACHER','warning','Class without class teacher',c.class_name||' has no assigned class teacher.','/setup/classes/'||c.id from public.academic_classes c where c.school_id=p_school_id and c.status='ACTIVE' and c.class_teacher_user_id is null
 union all select 2,'SUBJECT_NOT_OFFERED','info','Active subject not offered',coalesce(so.school_subject_code,ss.subject_code)||' · '||coalesce(so.display_name_override,ss.subject_name)||' is not assigned to a class.','/setup/classes/new' from public.school_subject_offerings so left join public.system_subjects ss on ss.id=so.system_subject_id where so.school_id=p_school_id and so.status='ACTIVE' and not exists(select 1 from public.class_subject_offerings co where co.school_subject_offering_id=so.id and co.status='ACTIVE')
 union all select 1,'OFFERING_WITHOUT_TEACHER','error','Subject offering without teacher',c.class_name||' · '||coalesce(so.school_subject_code,ss.subject_code)||' has no active primary teacher.','/setup/classes/'||c.id from public.class_subject_offerings co join public.academic_classes c on c.id=co.class_id join public.school_subject_offerings so on so.id=co.school_subject_offering_id left join public.system_subjects ss on ss.id=so.system_subject_id where co.school_id=p_school_id and co.status='ACTIVE' and not exists(select 1 from public.teacher_allocations ta where ta.class_subject_offering_id=co.id and ta.status='ACTIVE' and ta.allocation_role='PRIMARY_SUBJECT_TEACHER')
 union all select 2,'TEACHER_WITHOUT_ALLOCATION','info','Teacher without allocation',u.full_name||' has no active teaching allocation.','/people/users/'||u.id from public.school_memberships m join public.users u on u.id=m.user_id join public.roles r on r.id=m.role_id where m.school_id=p_school_id and m.status='ACTIVE' and r.code='TEACHER' and not exists(select 1 from public.teacher_allocations ta where ta.school_id=p_school_id and ta.teacher_id=u.id and ta.status='ACTIVE')
 union all select 1,'LEARNER_WITHOUT_ENROLMENT','error','Learner without active enrolment',l.admission_number||' · '||l.first_name||' '||l.last_name||' has no active class enrolment.','/school/learners/'||l.id from public.learners l where l.school_id=p_school_id and l.status='ACTIVE' and not exists(select 1 from public.learner_class_enrolments e where e.learner_id=l.id and e.status='ACTIVE' and e.effective_to is null)
 union all select 1,'CLASS_WITHOUT_SUBJECTS','error','Class with learners but no subjects',c.class_name||' has active learners but no active subject offering.','/setup/classes/'||c.id from public.academic_classes c where c.school_id=p_school_id and c.status='ACTIVE' and exists(select 1 from public.learner_class_enrolments e where e.class_id=c.id and e.status='ACTIVE' and e.effective_to is null) and not exists(select 1 from public.class_subject_offerings co where co.class_id=c.id and co.status='ACTIVE')
) i where public.is_active_school_member(p_school_id) or public.is_active_platform_admin()
$$;
revoke all on function public.get_academic_setup_health(uuid) from public,anon;
grant execute on function public.get_academic_setup_health(uuid) to authenticated;;
